\set ON_ERROR_STOP on
DO $$ BEGIN
 IF EXISTS (SELECT FROM pg_roles WHERE rolname='campus_runtime' AND (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls OR rolinherit)) THEN RAISE EXCEPTION 'Unsafe runtime role flags'; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='campus_runtime' AND rolcanlogin) THEN RAISE EXCEPTION 'Runtime login missing'; END IF;
 IF EXISTS (SELECT FROM pg_auth_members WHERE member='campus_runtime'::regrole) THEN RAISE EXCEPTION 'Runtime has role memberships'; END IF;
 IF EXISTS (SELECT FROM pg_class WHERE relowner='campus_runtime'::regrole) OR EXISTS (SELECT FROM pg_namespace WHERE nspowner='campus_runtime'::regrole) OR EXISTS (SELECT FROM pg_database WHERE datdba='campus_runtime'::regrole) THEN RAISE EXCEPTION 'Runtime owns database objects'; END IF;
 IF has_database_privilege('campus_runtime','campus','CREATE') OR has_database_privilege('campus_runtime','campus','TEMP') OR has_schema_privilege('campus_runtime','public','CREATE') THEN RAISE EXCEPTION 'Runtime can create objects'; END IF;
 IF NOT has_database_privilege('campus_runtime','campus','CONNECT') OR NOT has_schema_privilege('campus_runtime','public','USAGE') THEN RAISE EXCEPTION 'Runtime cannot connect/use schema'; END IF;
 IF has_table_privilege('campus_runtime','public.flyway_schema_history','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'Runtime can access migration history'; END IF;
 IF has_table_privilege('campus_runtime','public.campus_users','UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('campus_runtime','public.applications','DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('campus_runtime','public.interview_stages','TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'Excess runtime table privileges'; END IF;
 IF NOT has_table_privilege('campus_runtime','public.campus_users','SELECT') OR NOT has_table_privilege('campus_runtime','public.campus_users','INSERT') OR NOT has_table_privilege('campus_runtime','public.applications','UPDATE') OR NOT has_table_privilege('campus_runtime','public.interview_stages','DELETE') THEN RAISE EXCEPTION 'Missing runtime DML privileges'; END IF;
END $$;
DO $$ BEGIN
 IF NOT has_column_privilege('campus_runtime','public.campus_users','theme_preference','UPDATE') OR NOT has_column_privilege('campus_runtime','public.campus_users','email_verified_at','UPDATE') OR NOT has_column_privilege('campus_runtime','public.campus_users','password_hash','UPDATE') OR NOT has_column_privilege('campus_runtime','public.campus_users','credential_version','UPDATE') OR NOT has_column_privilege('campus_runtime','public.campus_users','reset_request_cutoff','UPDATE') THEN RAISE EXCEPTION 'Missing appearance, verification or credential update privileges'; END IF;
 IF EXISTS (SELECT FROM information_schema.columns WHERE table_schema='public' AND table_name='campus_users' AND column_name NOT IN ('theme_preference','email_verified_at','password_hash','credential_version','reset_request_cutoff') AND has_column_privilege('campus_runtime','public.campus_users',column_name,'UPDATE')) THEN RAISE EXCEPTION 'Runtime can alter protected account fields'; END IF;
 IF NOT has_table_privilege('campus_runtime','public.email_verification_tokens','SELECT,INSERT,UPDATE,DELETE') OR NOT has_table_privilege('campus_runtime','public.email_outbox','SELECT,INSERT,UPDATE,DELETE') OR NOT has_table_privilege('campus_runtime','public.auth_rate_limits','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Missing verification DML privileges'; END IF;
END $$;
DO $$ BEGIN
 IF NOT has_table_privilege('campus_runtime','public.password_reset_requests','SELECT') OR NOT has_table_privilege('campus_runtime','public.password_reset_requests','INSERT') OR NOT has_table_privilege('campus_runtime','public.password_reset_requests','UPDATE') OR NOT has_table_privilege('campus_runtime','public.password_reset_requests','DELETE') OR NOT has_table_privilege('campus_runtime','public.password_reset_tokens','SELECT') OR NOT has_table_privilege('campus_runtime','public.password_reset_tokens','INSERT') OR NOT has_table_privilege('campus_runtime','public.password_reset_tokens','UPDATE') OR NOT has_table_privilege('campus_runtime','public.password_reset_tokens','DELETE') THEN RAISE EXCEPTION 'Missing recovery DML privileges'; END IF;
 IF has_table_privilege('campus_runtime','public.password_reset_requests','TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('campus_runtime','public.password_reset_tokens','TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'Excess recovery table privileges'; END IF;
 IF NOT has_table_privilege('campus_runtime','public.auth_security_events','SELECT') OR NOT has_table_privilege('campus_runtime','public.auth_security_events','INSERT') OR has_table_privilege('campus_runtime','public.auth_security_events','UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'Unsafe audit privileges'; END IF;
 IF NOT has_table_privilege('campus_runtime','public.password_reset_control','SELECT') OR NOT has_column_privilege('campus_runtime','public.password_reset_control','health_intake_paused','UPDATE') OR has_table_privilege('campus_runtime','public.password_reset_control','INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_column_privilege('campus_runtime','public.password_reset_control','enabled','UPDATE') OR has_column_privilege('campus_runtime','public.password_reset_control','operator_intake_paused','UPDATE') OR has_column_privilege('campus_runtime','public.password_reset_control','id','UPDATE') THEN RAISE EXCEPTION 'Unsafe recovery control privileges'; END IF;
 IF NOT has_sequence_privilege('campus_runtime','public.auth_security_event_order','USAGE') OR has_sequence_privilege('campus_runtime','public.auth_security_event_order','SELECT,UPDATE') THEN RAISE EXCEPTION 'Unsafe recovery sequence privileges'; END IF;
 IF NOT EXISTS (SELECT FROM pg_sequences WHERE schemaname='public' AND sequencename='auth_security_event_order' AND cache_size=1 AND NOT cycle) THEN RAISE EXCEPTION 'Unsafe recovery sequence ordering'; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='campus_retention' AND rolcanlogin AND NOT (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls OR rolinherit)) OR EXISTS (SELECT FROM pg_auth_members WHERE member='campus_retention'::regrole) THEN RAISE EXCEPTION 'Unsafe retention role'; END IF;
 IF NOT has_table_privilege('campus_retention','public.auth_security_events','DELETE') OR NOT has_column_privilege('campus_retention','public.auth_security_events','id','SELECT') OR NOT has_column_privilege('campus_retention','public.auth_security_events','occurred_at','SELECT') OR has_table_privilege('campus_retention','public.auth_security_events','SELECT,INSERT,UPDATE,TRUNCATE,REFERENCES,TRIGGER') OR has_column_privilege('campus_retention','public.auth_security_events','account_subject','SELECT') OR has_table_privilege('campus_retention','public.campus_users','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Unsafe retention privileges'; END IF;
END $$;
